00027 BaseScreen* ConfigModeScreen::handle_input(Controller& controller, const worker_map_t& workers) {
00028 
00029   if (menu_open()) {
00030     return handle_menu_input(controller, workers, CONFIG_MODE_MENU, e_config_MENU_MAX);
00031   }
00032   else {
00033     auto button1 = workers.worker<ZenButton>(k_worker_button_1);
00034     auto button2 = workers.worker<ZenButton>(k_worker_button_2);
00035     auto button3 = workers.worker<ZenButton>(k_worker_button_3);
00036     if (button1->is_fresh() && button1->get_data().shortPress) {
00037       open_menu(true);
00038       M5.Lcd.clear();
00039       force_next_render();
00040     }
00041     if (button2->is_fresh() && button2->get_data().shortPress) {
00042       // screen specific action
00043       switch (_current_page) {
00044         case e_config_page_reset:
00045           controller.reset_settings();
00046           // Temp clear and post reset message to screen
00047           M5.Lcd.clear(LCD_COLOR_BACKGROUND);
00048           M5.Lcd.setRotation(3);
00049           M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
00050           M5.Lcd.setCursor(17, 78, &fonts::Font4);
00051           M5.Lcd.printf("DEVICE MEMORY RESET\n");
00052           M5.Lcd.setCursor(100, 120, &fonts::Font2);
00053           M5.Lcd.printf("Restarting device...\n");
00054           delay(1000);
00055           DeviceUtils::shutdown(true);
00056           break;
00057         case e_config_page_reset_all:
00058           M5.Lcd.clear(LCD_COLOR_BACKGROUND);
00059           M5.Lcd.setRotation(3);
00060           M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
00061           M5.Lcd.setCursor(30, 78, &fonts::Font4);
00062           M5.Lcd.printf("RESET IN PROGRESS\n");
00063           M5.Lcd.setCursor(5, 120, &fonts::Font2);
00064 
00065           M5.Lcd.printf("Removing all log files, This can take a while...\n");
00066           controller.factory_reset();
00067           M5.Lcd.clear(LCD_COLOR_BACKGROUND);
00068           M5.Lcd.setRotation(3);
00069           M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
00070           M5.Lcd.setCursor(27, 78, &fonts::Font4);
00071           M5.Lcd.printf("DEVICE MEMORY AND\n");
00072           M5.Lcd.setCursor(27, 110, &fonts::Font4);
00073           M5.Lcd.printf("SD HAVE BEEN RESET\n");
00074           M5.Lcd.setCursor(70, 160, &fonts::Font2);
00075           M5.Lcd.printf("Please turn off the device...\n");
00076           delay(UINT32_MAX); // Sleep for a long time.
00077           break;
00078         case e_config_page_main:
00079           _main_page_info_section = (_main_page_info_section + 1) % e_config_section_MAX;
00080           force_next_render();
00081         default:
00082           break;
00083       }
00084     }
00085     if (button3->is_fresh() && button3->get_data().shortPress) {
00086       return &MenuWindow_i;
00087     }
00088   }
00089 
00090   return nullptr;
00091 }
