00093 void ConfigModeScreen::render(const worker_map_t& workers, const handler_map_t& handlers, bool force) {
00094 
00095   if (menu_open()) {
00096     if (!force) {
00097       return;
00098     }
00099     return render_menu(CONFIG_MODE_MENU, e_config_MENU_MAX);
00100   }
00101 
00102   switch (_current_page) {
00103     case e_config_page_main:
00104       if (!force) {
00105         return;
00106       }
00107       return render_page_main(workers, handlers);
00108     case e_config_page_ap:
00109       return render_page_ap(workers, handlers);
00110     case e_config_page_wifi:
00111       return render_page_wifi(workers, handlers);
00112     case e_config_page_reset:
00113       return render_reset_device(workers, handlers);
00114     case e_config_page_reset_all:
00115       return render_reset_device_sd(workers, handlers);
00116     default:
00117       return;
00118   }
00119 }
