00121 void ConfigModeScreen::render_page_main(const worker_map_t& workers, const handler_map_t& handlers) {
00122   drawButton1("Options");
00123   char button_text[13];
00124   sprintf(button_text, "More (%d/%d)", _main_page_info_section + 1, e_config_section_MAX);
00125   drawButton2(button_text);
00126   drawButton3("Menu");
00127 
00128   clear_screen_content();
00129 
00130   M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
00131 
00132   // Temp print out device settings on screen
00133   const auto& config = *workers.worker<LocalStorage>(k_worker_local_storage);
00134   M5.Lcd.setCursor(0, 40, &fonts::Font2);
00135 
00136   if (_main_page_info_section == e_config_section_device) {
00137     M5.Lcd.printf("Device settings\n\n");
00138     M5.Lcd.printf("Display unit:   %s  \n", config.get_cpm_usvh() ? "CPM" : "uSv/h");
00139     M5.Lcd.printf("Alert threshold:   %d  \n", config.get_alert_threshold());
00140     M5.Lcd.printf("Logging drive/survey:   %s  \n", config.get_manual_logging() ? "Manual start" : "Automatic");
00141     M5.Lcd.printf("Measurements in log file:   %s  \n", config.get_log_void() ? "Valid and invalid" : "Only valid");
00142     M5.Lcd.printf("Screen dim after:   %d seconds  \n", config.get_screen_dim_timeout());
00143     M5.Lcd.printf("Screen off after:   %d seconds  \n", config.get_screen_off_timeout());
00144     M5.Lcd.printf("Screensaver:   %s  \n", config.get_animated_screensaver() ? "Enabled" : "Disabled");
00145   }
00146   if (_main_page_info_section == e_config_section_location) {
00147     M5.Lcd.printf("Location settings\n\n");
00148     M5.Lcd.printf("Fixed longitude:   %0.6f  \n", config.get_fixed_longitude());
00149     M5.Lcd.printf("Fixed latitude:   %0.6f  \n", config.get_fixed_latitude());
00150     M5.Lcd.printf("Fixed range:   %0.2f km  \n", config.get_fixed_range());
00151     M5.Lcd.printf("Maximum valid DOP:   %u   \n", config.get_dop_max());
00152   }
00153   if (_main_page_info_section == e_config_section_connection) {
00154     M5.Lcd.printf("Connection settings\n\n");
00155     M5.Lcd.printf("AP password:   %s  \n", config.get_ap_password());
00156     M5.Lcd.printf("local Wi-Fi ssid:   %s  \n", config.get_wifi_ssid());
00157     M5.Lcd.printf("local Wi-Fi password:   %s  \n", config.get_wifi_password());
00158     M5.Lcd.printf("API key:   %s  \n", config.get_api_key());
00159   }
00160 
00161 }
