00218 void ConfigModeScreen::enter_screen(Controller& controller) {
00219   switch (_current_page) {
00220     case e_config_page_main:
00221       // In case when entering from main menu, always set config menu index correctly
00222       _menu_index = e_config_page_main;
00223       break;
00224     case e_config_page_ap:
00225       WiFiWrapper_i.start_ap_server(controller.get_settings().get_device_id(), controller.get_settings().get_ap_password());
00226       controller.set_worker_active(k_worker_config_server, true);
00227       break;
00228     case e_config_page_wifi:
00229       WiFiWrapper_i.connect_wifi(controller.get_settings().get_wifi_ssid(), controller.get_settings().get_wifi_password());
00230       controller.set_worker_active(k_worker_config_server, true);
00231       break;
00232     case e_config_page_load_sd_config:
00233       if (controller.load_sd_config()) {
00234         set_status_message(F(" SD CONFIG LOADED, settings have been updated! "));
00235       }
00236       else {
00237         set_status_message(F(" LOAD CONFIG FAILED, no config or SD-card! "));
00238       }
00239       _current_page = e_config_page_main; // Back on main page
00240       open_menu(true);       // Re-enter menu
00241       break;
00242     case e_config_page_save_config_to_sd:
00243       if (controller.write_sd_config()) {
00244         set_status_message(F(" CONFIG SAVED, settings have been saved to SD! "));
00245       }
00246       else {
00247         set_status_message(F(" WRITE CONFIG FAILED, no SD-card! "));
00248       }
00249       _current_page = e_config_page_main; // Back on main page
00250       open_menu(true);       // Re-enter menu
00251       break;
00252     default:
00253       break;
00254   }
00255 }
00256 
00257 void ConfigModeScreen::leave_screen(Controller& controller) {
00258   switch (_current_page) {
00259     case e_config_page_ap:
00260       WiFiWrapper_i.stop_ap_server();
00261       controller.set_worker_active(k_worker_config_server, false);
00262       break;
00263     case e_config_page_wifi:
00264       WiFiWrapper_i.disconnect_wifi();
00265       controller.set_worker_active(k_worker_config_server, false);
00266       break;
00267     default:
00268       break;
00269   }
00270 
00271   // Set page to main in case we left through main menu
00272   _current_page = e_config_page_main;
00273   _main_page_info_section = e_config_section_device;
00274 }
